import sys

def single_number_brute(nums):
    seen = set()
    for x in nums:
        if x in seen:
            seen.remove(x)
        else:
            seen.add(x)
    return next(iter(seen))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(single_number_brute(nums))

import sys

def single_number_opt(nums):
    nums = sorted(nums)
    for i in range(1, len(nums), 2):
        if nums[i] != nums[i - 1]:
            return nums[i - 1]
    return nums[-1]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(single_number_opt(nums))

import sys

def single_number_best(nums):
    ans = 0
    for x in nums:
        ans ^= x
    return ans

